def cleanup(items):
    # BUG: Mutating list while iterating
    for item in items:
        if item.startswith('OLD-'):
            items.remove(item)
    return items

if __name__ == '__main__':
    data = ['OLD-1', 'OLD-2', 'KEEP-1', 'OLD-3', 'KEEP-2']
    result = cleanup(data)
    print(result)
